import { inputBaseClasses } from '@mui/material/InputBase';
import { outlinedInputClasses } from '@mui/material/OutlinedInput';
import { selectClasses, type SelectProps } from '@mui/material/Select';
import type { SxProps, Theme } from '@mui/material/styles';
import { svTokens } from '../../theme/tokens';

export function selectStyles(
  color: SelectProps['color'],
  hasLabel: boolean
): SxProps<Theme> {
  return (theme) => {
    const palette = (theme.vars ?? theme).palette;
    const swatch = palette[color as keyof typeof palette];
    const active =
      color === 'primary'
        ? `var(--SvSelect-accent, ${svTokens(theme).accent})`
        : swatch && typeof swatch === 'object' && 'main' in swatch
          ? (swatch.main as string)
          : svTokens(theme).accent;
    const outline = `& .${outlinedInputClasses.notchedOutline}`;
    return {
      minWidth: 0,
      borderRadius: '8px',
      fontSize: '13px',
      lineHeight: '24px',
      letterSpacing: '-0.0025em',
      backgroundColor: 'transparent',
      [outline]: {
        ...(!hasLabel && { top: 0, '& legend': { display: 'none' } }),
        borderWidth: '1px',
        borderColor: `var(--SvSelect-stroke, ${svTokens(theme).stroke})`,
      },
      [`&:hover:not(.${inputBaseClasses.disabled}):not(.${inputBaseClasses.error}) .${outlinedInputClasses.notchedOutline}, &.${inputBaseClasses.focused}:not(.${inputBaseClasses.disabled}):not(.${inputBaseClasses.error}) .${outlinedInputClasses.notchedOutline}`]:
        {
          borderWidth: '1px',
          borderColor: active,
        },
      [`&.${inputBaseClasses.error} .${outlinedInputClasses.notchedOutline}`]: {
        borderWidth: '1px',
        borderColor: `var(--SvSelect-error, ${palette.error.main})`,
      },
      [`&.${inputBaseClasses.disabled} .${outlinedInputClasses.notchedOutline}`]:
        {
          borderColor: `var(--SvSelect-stroke, ${svTokens(theme).stroke})`,
        },
      [`&:has(.${selectClasses.select}:focus-visible)`]: {
        outline: `2px solid ${svTokens(theme).focus}`,
        outlineOffset: '2px',
      },
      [`& .${selectClasses.select}`]: {
        minHeight: '24px',
        padding: '6px 44px 6px 8px',
        lineHeight: '24px',
        [`&.${selectClasses.disabled}`]: {
          WebkitTextFillColor: `var(--SvSelect-secondary, ${palette.text.secondary})`,
        },
      },
      [`& .${selectClasses.icon}`]: {
        width: '16px',
        height: '16px',
        fontSize: '16px',
        right: '12px',
        top: 'calc(50% - 8px)',
        color: `var(--SvSelect-secondary, ${palette.text.secondary})`,
      },
    };
  };
}
